#!/usr/bin/env python3
from pathlib import Path

p = Path('src/core/core_lower.c')
s = p.read_text()
if 'CORE_M106_ADDRESS' in s:
    print('M106 address diagnostic already applied')
    raise SystemExit(0)

old = '''    if (expression->kind == MINIC_EXPRESSION_ADDRESS_OF) {\n        MinicCoreLowerStatus status;\n\n        status = lower_address(context, expression->value.unary.operand, value_id);\n        if (status != MINIC_CORE_LOWER_OK) {\n            return status;\n        }\n        if (*value_id >= context->function->value_count) {\n            return MINIC_CORE_LOWER_ERROR;\n        }\n        if (minic_type_equal(context->function->values[*value_id].type, expression->type)) {\n            return MINIC_CORE_LOWER_OK;\n        }\n        /* M90_LEGACY_ARRAY_ADDRESS_OF: legacy local/member arrays keep their\n           element type plus array-object metadata. lower_address() therefore\n           yields the element-address representation, while C `&array` carries\n           pointer-to-array type. The address bits are identical; preserve the\n           semantic pointer type with Core's target-neutral scalar bitcast. */\n        {\n            const MinicExpression *addressed = minic_c0_program_expression(\n                context->body->program, expression->value.unary.operand);\n            MinicArrayObjectInfo array_info;\n\n            (void)memset(&array_info, 0, sizeof(array_info));\n            if (addressed != NULL &&\n                minic_c0_expression_array_object_info(\n                    context->body->program, addressed, &array_info) &&\n                minic_type_is_pointer(context->function->values[*value_id].type) &&\n                minic_type_is_pointer(expression->type)) {\n                return append_scalar_bitcast(\n                    context, expression->span, expression->type, *value_id, value_id);\n            }\n        }\n        return MINIC_CORE_LOWER_ERROR;\n    }\n'''
new = '''    if (expression->kind == MINIC_EXPRESSION_ADDRESS_OF) {\n        const MinicExpression *addressed = minic_c0_program_expression(\n            context->body->program, expression->value.unary.operand);\n        const MinicLocal *trace_local = NULL;\n        MinicArrayObjectInfo trace_array;\n        bool trace_has_array;\n        MinicCoreLowerStatus status;\n\n        (void)memset(&trace_array, 0, sizeof(trace_array));\n        trace_has_array = addressed != NULL &&\n            minic_c0_expression_array_object_info(\n                context->body->program, addressed, &trace_array);\n        if (addressed != NULL && addressed->kind == MINIC_EXPRESSION_LOCAL) {\n            trace_local = minic_c0_program_local(\n                context->body->program, addressed->value.local_id);\n        }\n        status = lower_address(context, expression->value.unary.operand, value_id);\n        if (context->source_function != NULL &&\n            strcmp(context->source_function->name, "force_compatible_cpus_allowed_ptr") == 0) {\n            (void)fprintf(stderr,\n                          "CORE_M106_ADDRESS stage=lower-address status=%d operand_kind=%d operand_cat=%d "\n                          "operand_ptr=%d operand_array=%d operand_record=%d has_array=%d materialized=%d "\n                          "array_count=%zu array_elem_ptr=%d array_elem_array=%d array_elem_record=%d "\n                          "local=%d local_array=%d local_count=%zu local_ptr=%d local_type_array=%d "\n                          "local_record=%d produced=%d produced_ptr=%d expr_ptr=%d\\n",\n                          (int)status, addressed != NULL ? (int)addressed->kind : -1,\n                          addressed != NULL ? (int)addressed->value_category : -1,\n                          addressed != NULL && minic_type_is_pointer(addressed->type) ? 1 : 0,\n                          addressed != NULL && minic_type_is_array(addressed->type) ? 1 : 0,\n                          addressed != NULL && minic_type_is_record(addressed->type) ? 1 : 0,\n                          trace_has_array ? 1 : 0,\n                          trace_has_array && trace_array.has_materialized_type ? 1 : 0,\n                          trace_has_array ? trace_array.element_count : 0U,\n                          trace_has_array && minic_type_is_pointer(trace_array.element_type) ? 1 : 0,\n                          trace_has_array && minic_type_is_array(trace_array.element_type) ? 1 : 0,\n                          trace_has_array && minic_type_is_record(trace_array.element_type) ? 1 : 0,\n                          trace_local != NULL ? 1 : 0,\n                          trace_local != NULL && trace_local->is_array ? 1 : 0,\n                          trace_local != NULL ? trace_local->element_count : 0U,\n                          trace_local != NULL && minic_type_is_pointer(trace_local->type) ? 1 : 0,\n                          trace_local != NULL && minic_type_is_array(trace_local->type) ? 1 : 0,\n                          trace_local != NULL && minic_type_is_record(trace_local->type) ? 1 : 0,\n                          status == MINIC_CORE_LOWER_OK && *value_id < context->function->value_count ? 1 : 0,\n                          status == MINIC_CORE_LOWER_OK && *value_id < context->function->value_count &&\n                              minic_type_is_pointer(context->function->values[*value_id].type) ? 1 : 0,\n                          minic_type_is_pointer(expression->type) ? 1 : 0);\n        }\n        if (status != MINIC_CORE_LOWER_OK) {\n            return status;\n        }\n        if (*value_id >= context->function->value_count) {\n            return MINIC_CORE_LOWER_ERROR;\n        }\n        if (minic_type_equal(context->function->values[*value_id].type, expression->type)) {\n            return MINIC_CORE_LOWER_OK;\n        }\n        /* M90_LEGACY_ARRAY_ADDRESS_OF */\n        {\n            MinicArrayObjectInfo array_info;\n\n            (void)memset(&array_info, 0, sizeof(array_info));\n            if (addressed != NULL &&\n                minic_c0_expression_array_object_info(\n                    context->body->program, addressed, &array_info) &&\n                minic_type_is_pointer(context->function->values[*value_id].type) &&\n                minic_type_is_pointer(expression->type)) {\n                MinicCoreLowerStatus cast_status = append_scalar_bitcast(\n                    context, expression->span, expression->type, *value_id, value_id);\n                if (context->source_function != NULL &&\n                    strcmp(context->source_function->name, "force_compatible_cpus_allowed_ptr") == 0) {\n                    (void)fprintf(stderr, "CORE_M106_ADDRESS stage=bitcast status=%d\\n",\n                                  (int)cast_status);\n                }\n                return cast_status;\n            }\n        }\n        return MINIC_CORE_LOWER_ERROR;\n    }\n'''
if s.count(old) != 1:
    raise SystemExit(f'address anchor count={s.count(old)}')
p.write_text(s.replace(old, new, 1))
print('M106 address diagnostic applied')
